+  let cursor = 0;
+
+  for (const token of tokens) {
+    const best = findClosestMatch(target, token, cursor);
+    if (!best) return -1;
+    totalScore -= (best.first - cursor) * 2;
+    totalScore -= best.last - best.first;
+    cursor = best.last + 1;
+  }
